import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')
# Check if we can enable software rendering fallback
debug = b'''<!doctype html>
<html>
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Arelorian</title>
<link rel="stylesheet" href="/assets/MMORPGClientCore-Bf6Bj3Nv.css">
<link rel="stylesheet" href="/assets/main-hKkHMhy1.css">
<script src="/assets/vendor-BVz5TCBb.js"></script>
<script src="/assets/MMORPGClientCore-DLUgQ5Dc.js"></script>
<script src="/assets/services-C3ENgesv.js"></script>
<script src="/assets/rolldown-runtime-DwmM5USC.js"></script>
<script src="/assets/main-CLZYnZ3S.js"></script>
<style>
html,body{margin:0;padding:0;width:100%;height:100%;background:#000}
#application-canvas{width:100vw;height:100vh}
#info{position:fixed;bottom:5px;left:5px;color:#0f0;font-size:10px;max-width:90%}
</style>
</head>
<body>
<canvas id="application-canvas"></canvas>
<div id="info"></div>
<script>
var i=document.getElementById('info');
var L=function(t){i.innerText=t;};
L('Testing...');
var c=document.getElementById('application-canvas');
// Try ALL rendering contexts
var webgl=c.getContext('webgl');
var webgl2=c.getContext('webgl2');
var exp=c.getContext('experimental-webgl');
L('webgl:'+(!!webgl)+' webgl2:'+(!!webgl2)+' exp:'+(!!exp));
// Try software fallback - ANGLE
if(!webgl){
  webgl=c.getContext('webgl',{failIfMajorPerformanceCaveat:false});
  L('webgl(soft):'+!!webgl);
}
if(!webgl){
  webgl=c.getContext('webgl',{powerPreference:'low-power'});
  L('webgl(low):'+!!webgl);
}
</script>
</body>
</html>'''
sftp = c.open_sftp()
with sftp.file('/tmp/debug.html', 'wb') as f:
    f.write(debug)
c.exec_command('cp /tmp/debug.html /opt/areloria/client/dist/index.html')
print('Software fallback test deployed')
c.close()
EOF
